#include <iostream>

int sequence(int n) {
  if (n == 0) {
    return 0;
  } else if (n == 1 || n == 2) {
    return -1;
  } else {
    return sequence(n - 1) + sequence(n - 2) + sequence(n - 3);
  }
}

int main() {
  int n = 4;
  int seq_num = sequence(n);
  std::cout << "The " << n << "th number in the sequence is: " << seq_num << std::endl;
  return 0;
}
